const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && rg --files -g 'AGENTS.md' -g '*gkeyll*' -g '*clone*' -g '*sparse*' -g '*.sh' -g 'pyproject.toml' -g '*SKILL.md' -g '!gkeyll/**' -g '!vendor/**' -g '!third_party/**' -g '!external/**'","max_output_tokens":5000}),
  tools.exec_command({cmd:"git status --short && rg -n --hidden -g '!.git/**' -g '!*.lock' -g '!*.ipynb' -g '!uv.lock' 'sparse.checkout|sparse-checkout|git clone|gkeyll' .agents/skills/development/SKILL.md .agents/skills/native/SKILL.md .agents/skills/design/SKILL.md AGENTS.md .gitmodules pyproject.toml CMakeLists.txt Makefile scripts .github .codex 2>/dev/null","max_output_tokens":8000})
]);
for (let i=0;i<results.length;i++) text({i,...results[i]});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md .agents/skills/design/SKILL.md .agents/skills/development/SKILL.md .agents/skills/native/SKILL.md","max_output_tokens":10000}),
  tools.exec_command({cmd:"git status --short && rg --files --hidden -g '!.git/**' -g '!gkeyll/.git/**' -g 'AGENTS.md' -g '*build*' -g '*gkeyll*' -g '*sparse*' && sed -n '1,240p' scripts/build_gkeyll.sh && git -C gkeyll status --short && git -C gkeyll sparse-checkout list && git -C gkeyll rev-parse --git-dir && git -C gkeyll ls-tree --name-only HEAD","max_output_tokens":9000})
]); for (let i=0;i<results.length;i++) text({i,...results[i]});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat .pre-commit-config.yaml gkeyll/AGENTS.md && rg -n --hidden -g '!.git/**' -g '!gkeyll/**' -g '!build/**' -g '!*.lock' -g '!*.ipynb' 'SPARSE_DIRS|sparse.checkout|sparse-checkout|build_gkeyll|core-only' scripts tests docs README.md setup.py .github .agents .codex && git --version && command -v pre-commit && command -v python && cat scripts/gkeyll-revision && git -C gkeyll rev-parse HEAD","max_output_tokens":8000}),
  tools.exec_command({cmd:"git -C gkeyll config --local --list && cat gkeyll/.git/info/sparse-checkout && git sparse-checkout -h && git -C gkeyll status --porcelain=v1 --untracked-files=all","max_output_tokens":4500})
]); for (let i=0;i<results.length;i++) text({i,...results[i]});

const results = await Promise.allSettled([
  tools.exec_command({cmd:"sh -n scripts/build_gkeyll.sh && git diff --check && git diff -- scripts/build_gkeyll.sh && sed -n '160,190p' README.md","max_output_tokens":4000}),
  tools.exec_command({cmd:"pre-commit run --files scripts/build_gkeyll.sh","max_output_tokens":4000,"yield_time_ms":1000})
]); for (let i=0;i<results.length;i++) text({i,...results[i]});
